//! `jsrt::string` against `fixtures/strings.json`, generated by Node 26.
//! Each case runs on `[u16]`, and on `str` when its inputs are well-formed.

mod common;

use std::collections::HashMap;

use common::*;
use jsrt::string::is_js_whitespace;
use jsrt::{JsStr, JsString};
use serde_json::Value;

fn strings() -> Value {
    fixture("strings.json")
}

#[test]
fn whitespace_set() {
    let f = strings();
    let expected: Vec<u16> = arr(&f["whitespace"])
        .iter()
        .map(|v| u16::try_from(int(v)).unwrap())
        .collect();
    let actual: Vec<u16> = (0..=u16::MAX).filter(|&u| is_js_whitespace(u)).collect();
    assert_eq!(actual, expected);
}

#[test]
fn trim() {
    let f = strings();
    for case in arr(&f["trim"]) {
        let s = units(&case[0]);
        let (t, ts, te) = (units(&case[1]), units(&case[2]), units(&case[3]));
        assert_eq!(s.js_trim(), &t[..], "trim {}", hex(&s));
        assert_eq!(s.js_trim_start(), &ts[..], "trimStart {}", hex(&s));
        assert_eq!(s.js_trim_end(), &te[..], "trimEnd {}", hex(&s));
        if let Some(st) = well_formed(&s) {
            assert_eq!(st.js_trim(), lossy(&t));
            assert_eq!(st.js_trim_start(), lossy(&ts));
            assert_eq!(st.js_trim_end(), lossy(&te));
        }
    }
}

fn case_map(f: &Value, key: &str) -> HashMap<u32, Vec<u16>> {
    arr(&f[key])
        .iter()
        .map(|e| (u32::try_from(int(&e[0])).unwrap(), units(&e[1])))
        .collect()
}

fn single_code_point(cp: u32) -> Vec<u16> {
    match char::from_u32(cp) {
        Some(c) => c.encode_utf16(&mut [0; 2]).to_vec(),
        None => vec![u16::try_from(cp).unwrap()],
    }
}

#[test]
fn case_every_code_point() {
    let f = strings();
    let lower = case_map(&f, "lower");
    let upper = case_map(&f, "upper");
    for cp in 0..=0x10FFFF {
        let s = single_code_point(cp);
        let want_lower = lower.get(&cp).unwrap_or(&s);
        let want_upper = upper.get(&cp).unwrap_or(&s);
        assert_eq!(
            s.js_to_lower_case().units(),
            &want_lower[..],
            "toLowerCase U+{cp:04X}"
        );
        assert_eq!(
            s.js_to_upper_case().units(),
            &want_upper[..],
            "toUpperCase U+{cp:04X}"
        );
        if let Some(st) = well_formed(&s) {
            assert_eq!(
                st.js_to_lower_case(),
                lossy(want_lower),
                "toLowerCase U+{cp:04X}"
            );
            assert_eq!(
                st.js_to_upper_case(),
                lossy(want_upper),
                "toUpperCase U+{cp:04X}"
            );
        }
    }
}

#[test]
fn case_contexts() {
    let f = strings();
    for case in arr(&f["caseContexts"]) {
        let s = units(&case[0]);
        let (lower, upper) = (units(&case[1]), units(&case[2]));
        assert_eq!(
            s.js_to_lower_case().units(),
            &lower[..],
            "toLowerCase {}",
            hex(&s)
        );
        assert_eq!(
            s.js_to_upper_case().units(),
            &upper[..],
            "toUpperCase {}",
            hex(&s)
        );
        if let Some(st) = well_formed(&s) {
            assert_eq!(
                st.js_to_lower_case(),
                lossy(&lower),
                "toLowerCase {}",
                hex(&s)
            );
            assert_eq!(
                st.js_to_upper_case(),
                lossy(&upper),
                "toUpperCase {}",
                hex(&s)
            );
        }
    }
}

#[test]
fn json_stringify() {
    let f = strings();
    let mut escaped: HashMap<u16, String> = HashMap::new();
    for case in arr(&f["json"]) {
        if case[0].is_array() {
            let s = units(&case[0]);
            let want = lossy(&units(&case[1]));
            assert_eq!(s.js_json_stringify(), want, "JSON.stringify {}", hex(&s));
            assert_eq!(format!("{:?}", JsString::from(&s[..])), want);
            if let Some(st) = well_formed(&s) {
                assert_eq!(st.js_json_stringify(), want);
            }
        } else {
            escaped.insert(
                u16::try_from(int(&case[0])).unwrap(),
                case[1].as_str().unwrap().to_owned(),
            );
        }
    }
    for unit in 0..=u16::MAX {
        let s = [unit];
        let want = escaped
            .get(&unit)
            .cloned()
            .unwrap_or_else(|| format!("\"{}\"", lossy(&s)));
        assert_eq!(s.js_json_stringify(), want, "JSON.stringify {unit:04x}");
    }
}

#[test]
fn compare() {
    let f = strings();
    for case in arr(&f["cmp"]) {
        let (a, b) = (units(&case[0]), units(&case[1]));
        let want = int(&case[2]).cmp(&0);
        assert_eq!(a.js_cmp(&b), want, "{} < {}", hex(&a), hex(&b));
        assert_eq!(JsString::from(&a[..]).cmp(&JsString::from(&b[..])), want);
        if let (Some(sa), Some(sb)) = (well_formed(&a), well_formed(&b)) {
            assert_eq!(sa.js_cmp(&sb), want, "{sa:?} < {sb:?}");
        }
    }
}

#[test]
fn index_methods() {
    let f = strings();
    for case in arr(&f["index"]) {
        let s = units(&case["s"]);
        let a = i32_of(&case["a"]);
        let b = opt_i32(&case["b"]);
        let ctx = format!("{} a={a} b={b:?}", hex(&s));
        let (slice, substring, substr) = (
            units(&case["slice"]),
            units(&case["substring"]),
            units(&case["substr"]),
        );
        let char_code = case["charCodeAt"]
            .as_u64()
            .map(|x| u16::try_from(x).unwrap());
        let code_point = case["codePointAt"]
            .as_u64()
            .map(|x| u32::try_from(x).unwrap());
        assert_eq!(s.js_len(), i32::try_from(s.len()).unwrap());
        assert_eq!(s.js_slice(a, b), &slice[..], "slice {ctx}");
        assert_eq!(s.js_substring(a, b), &substring[..], "substring {ctx}");
        assert_eq!(s.js_substr(a, b), &substr[..], "substr {ctx}");
        assert_eq!(s.js_char_code_at(a), char_code, "charCodeAt {ctx}");
        assert_eq!(s.js_code_point_at(a), code_point, "codePointAt {ctx}");
        if let Some(st) = well_formed(&s) {
            assert_eq!(st.js_len(), s.js_len());
            assert_eq!(st.js_slice(a, b), lossy(&slice), "slice {ctx}");
            assert_eq!(st.js_substring(a, b), lossy(&substring), "substring {ctx}");
            assert_eq!(st.js_substr(a, b), lossy(&substr), "substr {ctx}");
            assert_eq!(st.js_char_code_at(a), char_code, "charCodeAt {ctx}");
            assert_eq!(st.js_code_point_at(a), code_point, "codePointAt {ctx}");
        }
    }
}

#[test]
fn search_methods() {
    let f = strings();
    for case in arr(&f["search"]) {
        let (s, t) = (units(&case["s"]), units(&case["t"]));
        let p = i32_of(&case["p"]);
        let q = opt_i32(&case["q"]);
        let ctx = format!("s={} t={} p={p} q={q:?}", hex(&s), hex(&t));
        let index_of = i32_of(&case["indexOf"]);
        let last_index_of = i32_of(&case["lastIndexOf"]);
        let includes = case["includes"].as_bool().unwrap();
        let starts_with = case["startsWith"].as_bool().unwrap();
        let ends_with = case["endsWith"].as_bool().unwrap();
        assert_eq!(s.js_index_of(&t, p), index_of, "indexOf {ctx}");
        assert_eq!(
            s.js_last_index_of(&t, q),
            last_index_of,
            "lastIndexOf {ctx}"
        );
        assert_eq!(s.js_includes(&t, p), includes, "includes {ctx}");
        assert_eq!(s.js_starts_with(&t, p), starts_with, "startsWith {ctx}");
        assert_eq!(s.js_ends_with(&t, q), ends_with, "endsWith {ctx}");
        if let (Some(ss), Some(ts)) = (well_formed(&s), well_formed(&t)) {
            assert_eq!(ss.js_index_of(&ts, p), index_of, "indexOf {ctx}");
            assert_eq!(
                ss.js_last_index_of(&ts, q),
                last_index_of,
                "lastIndexOf {ctx}"
            );
            assert_eq!(ss.js_includes(&ts, p), includes, "includes {ctx}");
            assert_eq!(ss.js_starts_with(&ts, p), starts_with, "startsWith {ctx}");
            assert_eq!(ss.js_ends_with(&ts, q), ends_with, "endsWith {ctx}");
        }
    }
}

#[test]
fn split() {
    let f = strings();
    for case in arr(&f["split"]) {
        let (s, sep) = (units(&case["s"]), units(&case["sep"]));
        let limit = case["limit"].as_u64().map(|x| u32::try_from(x).unwrap());
        let want: Vec<Vec<u16>> = arr(&case["out"]).iter().map(units).collect();
        let ctx = format!("s={} sep={} limit={limit:?}", hex(&s), hex(&sep));
        let got: Vec<Vec<u16>> = s
            .js_split(&sep, limit)
            .into_iter()
            .map(<[u16]>::to_vec)
            .collect();
        assert_eq!(got, want, "split {ctx}");
        if let (Some(ss), Some(seps)) = (well_formed(&s), well_formed(&sep)) {
            let got: Vec<String> = ss
                .js_split(&seps, limit)
                .into_iter()
                .map(|c| c.into_owned())
                .collect();
            let want: Vec<String> = want.iter().map(|w| lossy(w)).collect();
            assert_eq!(got, want, "split {ctx}");
        }
    }
}

#[test]
fn replace() {
    let f = strings();
    for case in arr(&f["replace"]) {
        let (s, pat, rep) = (units(&case["s"]), units(&case["pat"]), units(&case["rep"]));
        let (one, all) = (units(&case["replace"]), units(&case["replaceAll"]));
        let ctx = format!("s={} pat={} rep={}", hex(&s), hex(&pat), hex(&rep));
        assert_eq!(s.js_replace(&pat, &rep).units(), &one[..], "replace {ctx}");
        assert_eq!(
            s.js_replace_all(&pat, &rep).units(),
            &all[..],
            "replaceAll {ctx}"
        );
        if let (Some(ss), Some(ps), Some(rs)) =
            (well_formed(&s), well_formed(&pat), well_formed(&rep))
        {
            assert_eq!(ss.js_replace(&ps, &rs), lossy(&one), "replace {ctx}");
            assert_eq!(ss.js_replace_all(&ps, &rs), lossy(&all), "replaceAll {ctx}");
        }
    }
}
